pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testFuzz_property(address caller, uint8 extraCalls) public {
        vm.assume(caller != address(0));
        vm.assume(extraCalls > 0);

        vm.prank(caller);
        c.initialize();

        bool secondCallSucceeded = true;
        for (uint8 i = 0; i < extraCalls; i++) {
            vm.prank(caller);
            try c.initialize() {
            } catch {
                secondCallSucceeded = false;
                break;
            }
        }
        assertTrue(!secondCallSucceeded);
    }
}
